var i=`1314-alfajores`;var r=`world-1314`;var a=`AR`;var n=`south-america`;var o=8;var s=62;var l={en:`Alfajores`,ua:`Альфахорес`};var d={en:`Alfajores is a dish from Argentina featuring chicken egg, all-purpose flour, cornstarch, baking powder. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Альфахорес, страва кухні країни Аргентина з такими основними складниками: куряче яйце, пшеничне борошно універсальне, кукурудзяний крохмаль, розпушувач тіста. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var u=[{en:`Beat the listed ingredients until pale and light; ensure butter and eggs are at room temperature when specified.`,ua:`Збийте зазначені складники до світлої пишної маси; за потреби використовуйте масло та яйця кімнатної температури.`,t:[`creaming-butter-sugar`,`whisking`],m:11,i:[[`unsalted-butter`,160,`g`],[`white-granulated-sugar`,130,`g`],[`chicken-egg`,2,`pcs`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:13,i:[[`all-purpose-flour`,330,`g`],[`cornstarch`,250,`g`],[`baking-powder`,13,`g`],[`vanilla-extract`,7,`ml`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:11,i:[]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 14 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 14 хвилин до готовності.`,t:[`baking`],m:14,i:[]},{en:`Sandwich completely cooled delicate cookies with dulce de leche, then roll their edges in coconut to make alfajores.`,ua:`Склейте повністю охолоджене крихке печиво дульсе де лече, а краї обкачайте в кокосовій стружці, формуючи альфахорес.`,t:[`layered-assembly`,`garnishing`],m:13,i:[[`dulce-de-leche`,420,`g`],[`desiccated-coconut`,100,`g`]]}];var g={slug:i,id:r,country:`AR`,region:n,servings:8,minutes:62,title:l,text:d,steps:u};export{a as country,g as default,r as id,s as minutes,n as region,o as servings,i as slug,u as steps,d as text,l as title};